package com.chainauth.blockchain;
import org.springframework.beans.factory.annotation.Value; import org.springframework.dao.DuplicateKeyException; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.web3j.protocol.core.methods.response.EthLog; import org.web3j.protocol.core.methods.response.Log; import java.math.BigInteger; import java.time.Instant;
@Component public class IdentityRegistryEventIndexer {
 private static final Logger log=LoggerFactory.getLogger(IdentityRegistryEventIndexer.class);
 private final BlockchainService chain; private final ChainEventCursorRepository cursors; private final IndexedChainEventRepository events; private final long startBlock;
 public IdentityRegistryEventIndexer(BlockchainService chain,ChainEventCursorRepository cursors,IndexedChainEventRepository events,@Value("${app.blockchain.event-start-block:0}") long startBlock){this.chain=chain;this.cursors=cursors;this.events=events;this.startBlock=Math.max(0,startBlock);}
 @Scheduled(fixedDelayString="${app.blockchain.event-poll-ms:15000}") public void index(){try{ChainEventCursor c=cursors.findById("identity-registry").orElseGet(()->{ChainEventCursor n=new ChainEventCursor();n.setNextBlock(startBlock);return n;}); if(c.getNextBlock()>startBlock&&c.getLastBlockHash()!=null){String canonical=chain.getBlockHash(c.getNextBlock()-1);if(!canonical.equalsIgnoreCase(c.getLastBlockHash())){long rewind=Math.max(startBlock,c.getNextBlock()-12);events.deleteByBlockNumberGreaterThanEqual(rewind);c.setNextBlock(rewind);c.setLastBlockHash(null);}} long latest=chain.getLatestBlock().longValueExact();if(c.getNextBlock()>latest)return;long end=Math.min(latest,c.getNextBlock()+999);for(EthLog.LogResult<?> result:chain.getEvents(BigInteger.valueOf(c.getNextBlock()),BigInteger.valueOf(end))){Object value=result.get();if(!(value instanceof Log log))continue;String key=log.getTransactionHash()+":"+log.getLogIndex();IndexedChainEvent e=new IndexedChainEvent();e.setEventKey(key);e.setBlockNumber(log.getBlockNumber().longValue());e.setBlockHash(log.getBlockHash());e.setTransactionHash(log.getTransactionHash());e.setRawLog(String.valueOf(value));try{events.save(e);}catch(DuplicateKeyException ignored){}}c.setNextBlock(end+1);c.setLastBlockHash(chain.getBlockHash(end));c.setUpdatedAt(Instant.now());cursors.save(c);}catch(Exception ex){log.warn("IdentityRegistry event indexing failed; cursor will be retried",ex);}}
}
